mapper.select:
SELECT COUNT(*)
FROM ADDRESS
WHERE member_id = #{memberId}

mapper.update:
UPDATE ADDRESS
SET
	is_default = 1,
	updated_at = NOW()
WHERE address_id = #{addressId}
  AND member_id = #{memberId}

mapper.delete:
DELETE FROM ADDRESS
WHERE address_id = #{addressId}
  AND member_id = #{memberId}
